func deleteAccount(phone: String, password: String, completion: @escaping (Bool, String) -> Void) {
    let url = URL(string: "https://ruyadream.com/velox/api/deactivate_account.php")!
    var request = URLRequest(url: url)
    request.httpMethod = "POST"
    request.setValue("application/json", forHTTPHeaderField: "Content-Type")

    let body: [String: String] = ["phone": phone, "password": password]
    request.httpBody = try? JSONSerialization.data(withJSONObject: body)

    URLSession.shared.dataTask(with: request) { data, response, error in
        guard let data = data, error == nil else {
            completion(false, "Network error")
            return
        }

        if let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
           let success = json["success"] as? Bool,
           let message = json["message"] as? String {
            completion(success, message)
        } else {
            completion(false, "Invalid response")
        }
    }.resume()
}
